setParent.example:
rect = newClientHudElem(self);
rect setParent(level.uiParent);
rect setShader("white", 200, 300);

shader_rect.full_example:
bg = newClientHudElem(self);
bg setParent(level.uiParent);
bg setShader("white", 200, 300);
bg.color = (0, 0, 0);
bg.alpha = 0.7;
bg.sort = 1;
bg setPoint("CENTER", "CENTER", 0, 0);

cleanup.destroy_pattern:
if (isDefined(self.menuBg))     self.menuBg destroy();
if (isDefined(self.menuTitle))  self.menuTitle destroy();
if (isDefined(self.menuCursor)) self.menuCursor destroy();
for (i = 0; i < self.menuOpts.size; i++)
    if (isDefined(self.menuOpts[i])) self.menuOpts[i] destroy();
